mapper.select:
select coalesce(sum(s.total), 0)
from pos_sale s
where 
  and s.sale_time >= #{startTime}
  and s.sale_time < #{endTime}

select count(1)
from pos_sale s
where 
  and s.sale_time >= #{startTime}
  and s.sale_time < #{endTime}

select count(distinct coalesce(nullif(s.create_by, ''), s.sale_no))
from pos_sale s
where s.sale_time >= #{startTime}

select count(1)
from pos_sale s
where 
  and s.sale_time >= #{startTime}
  and s.sale_time < #{endTime}
